CREATE TABLE IF NOT EXISTS workflow_definitions (workflow_id TEXT PRIMARY KEY, project_id TEXT NOT NULL UNIQUE REFERENCES projects(id) ON DELETE CASCADE, current_revision_id TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workflow_revisions (revision_id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL REFERENCES workflow_definitions(workflow_id) ON DELETE CASCADE, revision INTEGER NOT NULL CHECK (revision > 0), definition_json TEXT NOT NULL, immutable INTEGER NOT NULL CHECK (immutable = 1), created_at TEXT NOT NULL, UNIQUE (workflow_id, revision));
CREATE TABLE IF NOT EXISTS workflow_revision_stage_bindings (revision_id TEXT NOT NULL REFERENCES workflow_revisions(revision_id) ON DELETE CASCADE, contract_stage_id TEXT NOT NULL, task_stage_id TEXT NOT NULL REFERENCES workflow_stages(id), canonical_status TEXT NOT NULL, terminal_kind TEXT NOT NULL CHECK (terminal_kind IN ('none', 'completed', 'canceled')), stage_order INTEGER NOT NULL, PRIMARY KEY (revision_id, contract_stage_id), UNIQUE (revision_id, task_stage_id));
CREATE TABLE IF NOT EXISTS workflow_transition_rules (revision_id TEXT NOT NULL REFERENCES workflow_revisions(revision_id) ON DELETE CASCADE, action_key TEXT NOT NULL, transition_id TEXT NOT NULL, from_task_stage_id TEXT NOT NULL REFERENCES workflow_stages(id), to_task_stage_id TEXT NOT NULL REFERENCES workflow_stages(id), from_contract_stage_id TEXT NOT NULL, to_contract_stage_id TEXT NOT NULL, to_terminal_kind TEXT NOT NULL CHECK (to_terminal_kind IN ('none', 'completed', 'canceled')), legacy INTEGER NOT NULL DEFAULT 0 CHECK (legacy IN (0, 1)), PRIMARY KEY (revision_id, action_key), UNIQUE (revision_id, transition_id));
CREATE TABLE IF NOT EXISTS workflow_task_pins (task_id TEXT PRIMARY KEY REFERENCES tasks(id) ON DELETE CASCADE, workflow_id TEXT NOT NULL REFERENCES workflow_definitions(workflow_id), revision_id TEXT NOT NULL REFERENCES workflow_revisions(revision_id), pinned_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workflow_transition_requests (request_id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, idempotency_key TEXT NOT NULL UNIQUE, request_fingerprint TEXT NOT NULL, expected_state_version INTEGER NOT NULL, action_key TEXT NOT NULL, workflow_id TEXT NOT NULL, revision_id TEXT NOT NULL, transition_id TEXT NOT NULL, from_stage_id TEXT NOT NULL, to_stage_id TEXT NOT NULL, event_id TEXT NOT NULL UNIQUE REFERENCES workflow_ledger_events(event_id), event_hash TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE (task_id, expected_state_version));
CREATE TABLE IF NOT EXISTS workflow_authorizations (authorization_id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL, revision_id TEXT NOT NULL, authorization_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS workflow_transition_requests_task ON workflow_transition_requests(task_id, expected_state_version);
CREATE INDEX IF NOT EXISTS workflow_authorizations_scope ON workflow_authorizations(workflow_id, revision_id, authorization_id);
CREATE TRIGGER IF NOT EXISTS workflow_task_pins_on_task_insert AFTER INSERT ON tasks BEGIN INSERT OR IGNORE INTO workflow_task_pins (task_id, workflow_id, revision_id, pinned_at) SELECT NEW.id, workflow_id, current_revision_id, NEW.created_at FROM workflow_definitions WHERE project_id = NEW.project_id; END;
CREATE TRIGGER IF NOT EXISTS workflow_work_item_projections_on_task_insert AFTER INSERT ON tasks BEGIN INSERT OR IGNORE INTO workflow_work_item_projections (work_item_id, project_id, status, stage_id, task_version, projection_kind, imported_at, source_updated_at, last_event_sequence, last_event_hash) VALUES (NEW.id, NEW.project_id, NEW.status, NEW.stage_id, NEW.version, 'work_item.imported', NEW.created_at, NEW.updated_at, NULL, NULL); END;
